// ppwr - pull the useful parts out of an error payload
//
// n8n nests the interesting fields three levels down and the shape moves between versions, so
// every read is defensive. A missing field must not turn an error report into a second error.

const payload = $input.first().json || {};
const execution = payload.execution || {};
const workflow = payload.workflow || {};
const error = execution.error || payload.error || {};

const failingNode = (error.node && error.node.name) || execution.lastNodeExecuted || null;

// The failure is only attributable to a supplier if the failing item carried an id. Search the
// error payload rather than guessing, and accept that many failures are not attributable.
function findId(value, key, depth) {
  if (depth > 6 || value === null || value === undefined) return null;
  if (Array.isArray(value)) {
    for (const entry of value) {
      const hit = findId(entry, key, depth + 1);
      if (hit) return hit;
    }
    return null;
  }
  if (typeof value !== 'object') return null;
  if (typeof value[key] === 'string' && value[key] !== '') return value[key];
  for (const nested of Object.values(value)) {
    const hit = findId(nested, key, depth + 1);
    if (hit) return hit;
  }
  return null;
}

return [
  {
    json: {
      workflow_name: workflow.name || null,
      workflow_id: workflow.id || null,
      execution_id: execution.id || null,
      execution_url: execution.url || null,
      failing_node: failingNode,
      message: error.message || 'Unknown error',
      stack: error.stack || null,
      campaign_item_id: findId(payload, 'campaign_item_id', 0),
      submission_id: findId(payload, 'submission_id', 0),
      occurred_at: new Date().toISOString(),
      // Only the fallback. The address an operator actually wants is written into the meta
      // table and read by the next node, so setting it is not a repo change. This one stays a
      // placeholder because an address belonging to whoever built this is an address that keeps
      // receiving a forker's alerts.
      operator_email: 'operator@example.com',
    },
  },
];

